"""Home madura do VighnaStudy (H35 R3 — correção de geometria).

A interface desenha apenas a página inicial com Qt/QPainter. Não toca na
sidebar, banco de dados, histórico, motor de estudo ou regras de perfil.
O cabeçalho compartilhado continua o mesmo widget/código do Dashboard;
nenhum QComboBox ou sinal é duplicado.
"""

import base64
import math
from PySide6.QtCore import Qt, QRectF, QPointF
from PySide6.QtGui import (
    QColor, QPainter, QPainterPath, QLinearGradient, QRadialGradient,
    QPen, QBrush, QFont, QFontMetrics, QPixmap, QPolygonF
)
from PySide6.QtWidgets import (
    QWidget, QPushButton, QAbstractButton, QLabel, QFrame, QScrollArea,
    QHBoxLayout, QVBoxLayout, QSizePolicy, QMenu
)

_SYMBOL_B64 = ""


def _cor(valor):
    return QColor(valor)


def _font(tamanho, peso=QFont.Normal, familia="Segoe UI"):
    fonte = QFont(familia)
    fonte.setPixelSize(max(9, int(tamanho)))
    fonte.setWeight(peso)
    return fonte


class FundoHomeMaduro(QWidget):
    """Cenário estático, dimensionado ao espaço à direita da sidebar."""

    def definir_reducao_movimento(self, *args, **kwargs):
        # Não existe animação periódica nesta Home.
        return None

    def paintEvent(self, event):
        p = QPainter(self)
        p.setRenderHint(QPainter.Antialiasing, True)
        w = float(self.width()); h = float(self.height())
        if w < 2 or h < 2:
            p.end(); return

        base = QLinearGradient(0, 0, w, h)
        base.setColorAt(0.0, _cor("#06192b"))
        base.setColorAt(0.48, _cor("#03172a"))
        base.setColorAt(1.0, _cor("#04172a"))
        p.fillRect(self.rect(), base)

        # Vinheta azul central discreta.
        halo = QRadialGradient(QPointF(w * .51, h * .45), max(w, h) * .68)
        halo.setColorAt(0, QColor(0, 90, 150, 40))
        halo.setColorAt(1, QColor(0, 15, 34, 0))
        p.fillRect(self.rect(), QBrush(halo))

        # Superfícies geométricas superiores à esquerda, como a referência.
        topo = QPainterPath()
        topo.moveTo(0, 0)
        topo.lineTo(w * .31, 0)
        topo.cubicTo(w*.19,h*.07,w*.14,h*.15,0,h*.27)
        topo.closeSubpath()
        topo_cor = QLinearGradient(0, 0, w*.30, h*.34)
        topo_cor.setColorAt(0, QColor(4, 49, 79, 242))
        topo_cor.setColorAt(1, QColor(7, 71, 114, 110))
        p.fillPath(topo, topo_cor)

        aba = QPainterPath()
        aba.moveTo(0, h*.23)
        aba.cubicTo(w*.09,h*.09,w*.19,h*.03,w*.28,0)
        aba.lineTo(w*.37,0)
        aba.cubicTo(w*.22,h*.12,w*.10,h*.24,0,h*.43)
        aba.closeSubpath()
        p.fillPath(aba, QColor(2, 26, 49, 156))
        p.setPen(QPen(QColor(17, 132, 184, 100), 1.0))
        p.drawPath(topo)

        # Ondas geométricas inferiores à direita (sem bordas pesadas).
        inferior = QPainterPath()
        inferior.moveTo(w*.50, h)
        inferior.cubicTo(w*.69,h*.85,w*.88,h*.90,w,h*.72)
        inferior.lineTo(w,h)
        inferior.closeSubpath()
        baixo = QLinearGradient(w*.6,h*.86,w,h)
        baixo.setColorAt(0, QColor(3, 43, 76, 85))
        baixo.setColorAt(1, QColor(5, 90, 139, 200))
        p.fillPath(inferior,baixo)
        p.setPen(QPen(QColor(0, 180, 243, 103), 1.2))
        p.drawPath(inferior)
        baixo_2=QPainterPath()
        baixo_2.moveTo(w*.74,h)
        baixo_2.cubicTo(w*.87,h*.92,w*.98,h*.88,w,h*.82)
        baixo_2.lineTo(w,h)
        baixo_2.closeSubpath()
        p.fillPath(baixo_2,QColor(0, 50, 90, 123))
        p.setPen(QPen(QColor(14, 118, 182, 105), 1.0))
        p.drawPath(baixo_2)
        p.end()



# PNG oficial fornecido pelo usuário; enquadramento sem redesenhar a marca.

# Logo oficial com transparencia verdadeira, reduzida com Lanczos de alta qualidade.
_HOME_LOGO_HD_1X_B64 = """"""
_HOME_LOGO_HD_2X_B64 = """"""

class LogoHomeMaduro(QWidget):
    """Marca oficial da Home, carregada integralmente do PNG fornecido.

    Renderiza o logotipo como imagem única em lugar de reconstruir símbolo e
    tipografia com QPainter, preservando seu desenho original. O PNG está
    incorporado ao módulo para não depender de arquivos externos do Windows.
    """

    def __init__(self, parent=None):
        super().__init__(parent)
        self.setObjectName("homeLogoOficial")
        self.setMinimumHeight(155)
        self.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Fixed)
        # Versões 1x e 2x pré-renderizadas com filtro Lanczos a partir da
        # imagem original, ambas com fundo realmente transparente.
        self._logo_hd_1x = QPixmap()
        self._logo_hd_1x.loadFromData(base64.b64decode(_HOME_LOGO_HD_1X_B64), "PNG")
        self._logo_hd_2x = QPixmap()
        self._logo_hd_2x.loadFromData(base64.b64decode(_HOME_LOGO_HD_2X_B64), "PNG")
        self.setAccessibleName("VighnaStudy — marca oficial")

    def paintEvent(self, event):
        p = QPainter(self)
        p.setRenderHint(QPainter.Antialiasing, True)
        p.setRenderHint(QPainter.SmoothPixmapTransform, True)
        w = float(self.width())
        h = float(self.height())

        # Reserva a base para a assinatura preexistente. Sem esticar a marca,
        # não desenha as palavras Vighna e Study uma segunda vez.
        faixa_assinatura = 39.0
        area_logo_h = max(1.0, h - faixa_assinatura - 3.0)
        # Em monitores HiDPI a variante 2x evita ampliar uma fonte 1x.
        # A variante 1x mantém os pixels já filtrados na escala padrão.
        logo = self._logo_hd_2x if self.devicePixelRatioF() >= 1.20 else self._logo_hd_1x
        if logo.isNull():
            logo = self._logo_hd_2x if not self._logo_hd_2x.isNull() else self._logo_hd_1x
        if not logo.isNull():
            proporcao = logo.width() / max(1, logo.height())
            desenho_h = min(area_logo_h, max(1.0, w * 0.89 / proporcao))
            desenho_w = desenho_h * proporcao
            x = (w - desenho_w) / 2.0
            y = max(0.0, (area_logo_h - desenho_h) / 2.0)
            p.drawPixmap(
                QRectF(x, y, desenho_w, desenho_h),
                logo,
                QRectF(logo.rect()),
            )
        else:
            # Falha rara de decodificação: não reincide no símbolo antigo.
            font = _font(min(58, max(28, int(w * 0.052))), QFont.Bold)
            p.setFont(font)
            p.setPen(QColor("#EAF7FF"))
            p.drawText(QRectF(0, 10, w, area_logo_h), Qt.AlignCenter, "VighnaStudy")

        # Mantém a assinatura institucional aprovada na Home.
        subtitulo = "S I S T E M A   D E   E S T U D O S   A V A N Ç A D O"
        sub_font = _font(min(20, max(10, int(w * 0.015))), QFont.Medium)
        p.setFont(sub_font)
        metrics = QFontMetrics(sub_font)
        tw = metrics.horizontalAdvance(subtitulo)
        if tw > w * 0.77:
            sub_font = _font(max(9, int(sub_font.pixelSize() * (w * 0.77) / tw)), QFont.Medium)
            p.setFont(sub_font)
            tw = QFontMetrics(sub_font).horizontalAdvance(subtitulo)
        mid = w / 2.0
        y = h - 21
        p.setPen(QColor("#E0EAF7"))
        p.drawText(QRectF(mid - tw / 2, h - 48, tw, 32), Qt.AlignCenter, subtitulo)
        gap = 24
        p.setPen(QPen(QColor("#05CAE9"), 2.2))
        p.drawLine(QPointF(max(0, mid - tw / 2 - gap - 72), y - 16),
                   QPointF(mid - tw / 2 - gap, y - 16))
        p.drawLine(QPointF(mid + tw / 2 + gap, y - 16),
                   QPointF(min(w, mid + tw / 2 + gap + 72), y - 16))
        p.end()


class CartaoHomeMaduro(QAbstractButton):
    """Botão acessível clicável com pintura própria, isolado dos QSS de QPushButton.

    QAbstractButton mantém clicked, Enter/Espaço, mouse e foco sem depender
    das regras globais de tamanho dos QPushButton do programa.
    """

    def __init__(self,titulo,descricao,tipo,callback,parent=None):
        super().__init__(parent)
        self.titulo=titulo
        self.descricao=descricao
        self.tipo=tipo
        self._hover=False
        self.setObjectName("homeMaduroCard_"+tipo)
        # O cartao e inteiramente desenhado pelo paintEvent. Fora do retangulo
        # arredondado o pixel deve mostrar o FundoHomeMaduro, nunca o fundo
        # opaco que um QSS global pode atribuir a QAbstractButton.
        self.setAutoFillBackground(False)
        self.setAttribute(Qt.WA_NoSystemBackground, True)
        self.setAttribute(Qt.WA_TranslucentBackground, True)
        self.setCursor(Qt.PointingHandCursor)
        self.setFocusPolicy(Qt.StrongFocus)
        # H46 R1: não ponderar largura pelo sizeHint/texto do cartão.
        # O QHBoxLayout divide o espaço disponível igualmente entre os três.
        self.setSizePolicy(QSizePolicy.Ignored, QSizePolicy.Fixed)
        self.setMinimumWidth(200)
        # Evita a altura ~38px observada quando a folha QSS global comprime botões.
        self.setFixedHeight(224)
        # Título e descrição já estão visíveis; evita tooltip redundante.
        self.setAccessibleName(titulo)
        self.setAccessibleDescription(descricao)
        if callback is not None:
            self.clicked.connect(callback)
        else:
            self.setEnabled(False)

    def enterEvent(self,event):
        self._hover=True
        self.update()
        super().enterEvent(event)

    def leaveEvent(self,event):
        self._hover=False
        self.update()
        super().leaveEvent(event)

    def focusInEvent(self,event):
        super().focusInEvent(event)
        self.update()

    def focusOutEvent(self,event):
        super().focusOutEvent(event)
        self.update()

    @staticmethod
    def _desenhar_icone(p,tipo,cx,cy,tamanho):
        p.save()
        p.translate(cx,cy)
        p.scale(tamanho/100.0,tamanho/100.0)
        p.setBrush(Qt.NoBrush)
        branco=QColor("#F0F5FA");ciano=QColor("#08CFFF")
        if tipo=="estudo":
            # Livro aberto, páginas sobrepostas, com base iluminada.
            p.setPen(QPen(ciano,5,Qt.SolidLine,Qt.RoundCap,Qt.RoundJoin))
            brilho=QPainterPath()
            brilho.moveTo(-51,28);brilho.lineTo(-51,-25)
            brilho.lineTo(-41,-24)
            p.drawPath(brilho)
            p.drawLine(QPointF(51,28),QPointF(51,-25))
            p.setPen(QPen(branco,5,Qt.SolidLine,Qt.RoundCap,Qt.RoundJoin))
            livro=QPainterPath()
            livro.moveTo(0,29)
            livro.cubicTo(-14,14,-27,8,-42,11)
            livro.lineTo(-42,-33)
            livro.cubicTo(-22,-39,-10,-29,0,-21)
            livro.cubicTo(10,-29,22,-39,42,-33)
            livro.lineTo(42,11)
            livro.cubicTo(27,8,14,14,0,29)
            p.drawPath(livro)
            p.setPen(QPen(ciano,4,Qt.SolidLine,Qt.RoundCap,Qt.RoundJoin))
            p.drawLine(QPointF(-48,29),QPointF(0,36))
            p.drawLine(QPointF(0,36),QPointF(48,29))
        elif tipo=="simulados":
            p.setPen(QPen(branco,5,Qt.SolidLine,Qt.RoundCap,Qt.RoundJoin))
            p.drawRoundedRect(QRectF(-31,-39,62,78),7,7)
            p.drawRoundedRect(QRectF(-13,-45,26,13),5,5)
            for y in (-17,6):
                p.setPen(QPen(ciano,5,Qt.SolidLine,Qt.RoundCap,Qt.RoundJoin))
                p.drawLine(QPointF(-19,y),QPointF(-14,y+5))
                p.drawLine(QPointF(-14,y+5),QPointF(-6,y-7))
                p.setPen(QPen(branco,4,Qt.SolidLine,Qt.RoundCap,Qt.RoundJoin))
                p.drawLine(QPointF(3,y),QPointF(21,y))
            p.drawLine(QPointF(3,28),QPointF(21,28))
        elif tipo=="dashboard":
            # Análise: eixos, barras crescentes e linha de tendência. Ícone
            # original desenhado em Qt, sem recursos externos ou animação.
            p.setPen(QPen(branco,4.3,Qt.SolidLine,Qt.RoundCap,Qt.RoundJoin))
            p.drawLine(QPointF(-41,36),QPointF(39,36))
            p.drawLine(QPointF(-41,36),QPointF(-41,-32))
            p.setPen(Qt.NoPen)
            p.setBrush(QColor("#4C95B8"))
            p.drawRoundedRect(QRectF(-28,9,14,25),2,2)
            p.drawRoundedRect(QRectF(-4,-5,14,39),2,2)
            p.drawRoundedRect(QRectF(20,-23,14,57),2,2)
            p.setBrush(Qt.NoBrush)
            p.setPen(QPen(ciano,5,Qt.SolidLine,Qt.RoundCap,Qt.RoundJoin))
            tendencia=QPainterPath()
            tendencia.moveTo(-27,4)
            tendencia.lineTo(-5,-12)
            tendencia.lineTo(11,-8)
            tendencia.lineTo(32,-33)
            p.drawPath(tendencia)
            p.drawLine(QPointF(21,-33),QPointF(32,-33))
            p.drawLine(QPointF(32,-33),QPointF(32,-22))
        elif tipo=="edital":
            p.setPen(QPen(branco,5,Qt.SolidLine,Qt.RoundCap,Qt.RoundJoin))
            folha=QPainterPath()
            folha.moveTo(-35,-41);folha.lineTo(13,-41)
            folha.lineTo(35,-19);folha.lineTo(35,36)
            folha.quadTo(35,41,30,41)
            folha.lineTo(-35,41)
            folha.closeSubpath()
            p.drawPath(folha)
            p.drawLine(QPointF(13,-41),QPointF(13,-19))
            p.drawLine(QPointF(13,-19),QPointF(35,-19))
            for y in (-18,-5,8):
                p.drawLine(QPointF(-22,y),QPointF(14,y))
            # Estrela dourada - elemento pontual da marca.
            estrela=QPolygonF()
            for i in range(10):
                ang=-math.pi/2+i*math.pi/5
                raio=24 if i%2==0 else 10
                estrela.append(QPointF(26+math.cos(ang)*raio,24+math.sin(ang)*raio))
            p.setPen(Qt.NoPen)
            p.setBrush(QColor("#F6B641"))
            p.drawPolygon(estrela)
        p.restore()

    def paintEvent(self,event):
        """Hierarquia com contraste controlado, sem CTAs ou linhas decorativas."""
        p=QPainter(self)
        p.setRenderHint(QPainter.Antialiasing,True)
        w=float(self.width());h=float(self.height())
        principal=self.tipo=="estudo"
        em_foco=self.hasFocus()
        realce=self._hover or em_foco
        rect=QRectF(2.5,2.5,max(1.0,w-5),max(1.0,h-5))

        fundo=QLinearGradient(0,0,w,h)
        if principal:
            fundo.setColorAt(0,QColor("#123B54") if realce else QColor("#10334B"))
            fundo.setColorAt(.65,QColor("#0A293E"))
            fundo.setColorAt(1,QColor("#082137"))
        else:
            fundo.setColorAt(0,QColor("#12324A") if realce else QColor("#102B40"))
            fundo.setColorAt(.65,QColor("#0A2338"))
            fundo.setColorAt(1,QColor("#081E32"))
        p.setPen(Qt.NoPen)
        p.setBrush(fundo)
        p.drawRoundedRect(rect,22,22)

        # Ação primária: ciano contido, sem alterar a altura ou a tipografia.
        # Foco pelo teclado visível e prioritário para acessibilidade.
        if em_foco:
            borda=QColor("#73E7F5");espessura=2.1
        elif realce:
            borda=QColor("#3AC6E0");espessura=1.7
        elif principal:
            borda=QColor("#15AEC9");espessura=1.6
        else:
            borda=QColor("#446B84");espessura=1.15
        p.setPen(QPen(borda,espessura))
        p.setBrush(Qt.NoBrush)
        p.drawRoundedRect(rect,22,22)

        icon_size=min(78,max(60,int(h*.32)))
        self._desenhar_icone(p,self.tipo,w/2,h*.33,icon_size)
        titulo_f=_font(28,QFont.Bold)
        if QFontMetrics(titulo_f).horizontalAdvance(self.titulo)>w-28:
            titulo_f=_font(25,QFont.Bold)
        p.setFont(titulo_f)
        p.setPen(QColor("#F5F9FC"))
        p.drawText(QRectF(12,h*.57,w-24,h*.16),
                   Qt.AlignHCenter|Qt.AlignVCenter,self.titulo)

        desc_f=_font(16,QFont.Normal)
        if QFontMetrics(desc_f).horizontalAdvance(self.descricao)>w-24:
            desc_f=_font(14,QFont.Normal)
        p.setFont(desc_f)
        p.setPen(QColor("#B8CCDD"))
        p.drawText(QRectF(11,h*.75,w-22,h*.11),
                   Qt.AlignHCenter|Qt.AlignVCenter,self.descricao)
        p.end()


def criar_portal_inicio(abrir_dashboard, abrir_busca, abrir_questoes,
                        abrir_simulados=None, abrir_recursos=None,
                        cabecalho_compartilhado=None, abrir_edital=None):
    """Mantém o contrato original e os destinos; nenhum novo motor acadêmico."""
    pagina=QWidget()
    pagina.setObjectName("portalInicioPage")
    pagina.setSizePolicy(QSizePolicy.Expanding,QSizePolicy.Expanding)
    raiz=QVBoxLayout(pagina)
    raiz.setContentsMargins(0,0,0,0)
    raiz.setSpacing(0)
    scroll=QScrollArea(pagina)
    scroll.setObjectName("portalInicioScroll")
    scroll.setFrameShape(QFrame.NoFrame)
    scroll.setWidgetResizable(True)
    scroll.setHorizontalScrollBarPolicy(Qt.ScrollBarAlwaysOff)
    conteudo=FundoHomeMaduro()
    conteudo.setObjectName("portalInicioConteudo")
    conteudo.setMinimumSize(795,660)
    coluna=QVBoxLayout(conteudo)
    coluna.setContentsMargins(52,22,52,24)
    coluna.setSpacing(0)

    header=QHBoxLayout()
    header.setContentsMargins(0,0,0,0)
    header.addStretch(1)
    if cabecalho_compartilhado is not None:
        # Mesmo perfil, mesmo QComboBox e mesmas ligações. Sem duplicação.
        cabecalho_compartilhado.setFixedWidth(280)
        cabecalho_compartilhado.setFixedHeight(58)
        cabecalho_compartilhado.setObjectName("dashboardTopBar")
        gerenciar=cabecalho_compartilhado.findChild(QPushButton,"premiumHeaderManageButton")
        if gerenciar is not None:
            # Evita botão extra no mockup, preservando a ação real no menu.
            gerenciar.hide()
            cabecalho_compartilhado.setToolTip(
                "Perfil ativo — botão direito para gerenciar perfis"
            )
            cabecalho_compartilhado.setContextMenuPolicy(Qt.CustomContextMenu)
            def _abrir_gerenciamento(pos, _botao=gerenciar,
                                    _cabecalho=cabecalho_compartilhado):
                menu = QMenu(_cabecalho)
                opcao = menu.addAction("Gerenciar perfis")
                escolhido = menu.exec(_cabecalho.mapToGlobal(pos))
                if escolhido is opcao:
                    _botao.click()
            cabecalho_compartilhado.customContextMenuRequested.connect(
                _abrir_gerenciamento
            )
        header.addWidget(cabecalho_compartilhado,0,Qt.AlignRight|Qt.AlignTop)
        pagina.portal_perfil_label=None
        pagina._home_cabecalho_compartilhado=cabecalho_compartilhado
    else:
        rotulo=QLabel("Perfil ativo",conteudo)
        rotulo.setObjectName("homeFallbackPerfil")
        header.addWidget(rotulo)
        pagina.portal_perfil_label=rotulo
    coluna.addLayout(header)
    coluna.addSpacing(42)

    logo=LogoHomeMaduro(conteudo)
    logo.setFixedHeight(171)
    coluna.addWidget(logo)
    coluna.addSpacing(52)

    # Contêiner de altura explícita: o layout vertical não pode comprimir a
    # faixa dos três cartões para a altura de um QPushButton convencional.
    faixa_cartoes=QWidget(conteudo)
    faixa_cartoes.setObjectName("portalInicioCardsContainer")
    # Container puramente geometrico: nao deve pintar um retangulo atras dos
    # cartoes nem nas frestas entre eles, inclusive quando ha QSS global.
    faixa_cartoes.setAutoFillBackground(False)
    faixa_cartoes.setAttribute(Qt.WA_NoSystemBackground, True)
    faixa_cartoes.setAttribute(Qt.WA_TranslucentBackground, True)
    faixa_cartoes.setSizePolicy(QSizePolicy.Expanding,QSizePolicy.Fixed)
    faixa_cartoes.setFixedHeight(224)
    cards=QHBoxLayout(faixa_cartoes)
    cards.setSpacing(19)
    cards.setContentsMargins(0,0,0,0)
    # O contrato original passa o método voltar_inicio como abrir_dashboard.
    # Seu proprietário é a janela principal; usamos a rota JÁ EXISTENTE para
    # Central de Análises, sem criar um segundo Dashboard nem editar main.py.
    controlador=getattr(abrir_dashboard,"__self__",None)
    abrir_central_analises=getattr(controlador,"abrir_painel_analitico",None)
    if not callable(abrir_central_analises):
        raise RuntimeError("Home: rota para Central de Análises indisponível")
    especificacoes=(
        ("Iniciar Estudo","Estudo automático, manual e simulados","estudo",abrir_dashboard),
        ("Dashboard","Análise de desempenho","dashboard",abrir_central_analises),
        ("Meu Edital","Conteúdos e cobertura","edital",abrir_edital),
    )
    pagina._home_cards=[]
    for titulo,descricao,tipo,abrir in especificacoes:
        cartao=CartaoHomeMaduro(titulo,descricao,tipo,abrir,conteudo)
        cartao.setFixedHeight(224)
        # H45 R1: geometrias iguais (1:1:1). O destaque do estudo e feito
        # exclusivamente pelas cores do paintEvent, nunca pela largura.
        # Assim, o centro do Dashboard coincide com o eixo da logo.
        cards.addWidget(cartao, 1)
        pagina._home_cards.append(cartao)
    # Os três cartões têm o mesmo peso mesmo após eventuais recalculos Qt.
    for indice in range(3):
        cards.setStretch(indice, 1)
    coluna.addWidget(faixa_cartoes,0)
    pagina._home_faixa_cartoes=faixa_cartoes
    coluna.addStretch(1)
    coluna.addSpacing(20)
    scroll.setWidget(conteudo)
    raiz.addWidget(scroll,1)
    pagina._home_scroll=scroll
    pagina._home_conteudo=conteudo
    pagina._home_maduro=True
    return pagina


def aplicar_estilo_portal(pagina, tema):
    """QSS restrito à Home; Qt/QPainter controla o visual dos cartões."""
    pagina.setStyleSheet("""
    QWidget#portalInicioPage { background: #03172a; border: none; }
    QScrollArea#portalInicioScroll { background: transparent; border: none; }
    QWidget#portalInicioConteudo { border: none; }
    /* Evita a faixa opaca do widget geométrico atrás dos três cartões. */
    QWidget#portalInicioCardsContainer { background-color: transparent; border: none; }
    /* O QPainter desenha bordas e preenchimento, não o QSS dos botões. */
    QAbstractButton#homeMaduroCard_estudo,
    QAbstractButton#homeMaduroCard_dashboard,
    QAbstractButton#homeMaduroCard_edital {
        background-color: transparent; border: none;
    }
    QLabel#homeFallbackPerfil { color: #eef8ff; font-size: 16px; }
    QScrollBar:vertical { background: #071a2c; width: 7px; margin: 0; }
    QScrollBar::handle:vertical { background: #1e587d; border-radius: 3px; min-height: 28px; }
    QScrollBar::add-line:vertical, QScrollBar::sub-line:vertical { height: 0px; }
    """)
    header=getattr(pagina,"_home_cabecalho_compartilhado",None)
    if header is not None:
        estilizar_perfil_maduro(header)


def estilizar_perfil_maduro(painel):
    """Compacta apenas o cabeçalho compartilhado; preserva o seletor real."""
    painel.setStyleSheet("""
    QFrame#dashboardTopBar {
        background: rgba(7, 31, 51, 230);
        border: 1px solid #315D79;
        border-radius: 14px;
    }
    QFrame#dashboardTopBar QFrame#topProfileBar {
        background: transparent; border: none; border-radius: 0px;
    }
    QFrame#dashboardTopBar QLabel#topProfileLabel {
        background: transparent; border: none;
    }
    QFrame#dashboardTopBar QLabel#premiumHeaderProfileIcon {
        color: #D5E8F2; background: transparent; border: none;
    }
    QFrame#dashboardTopBar QComboBox#topProfileCombo {
        background: transparent; color: #EFF7FB;
        border: none; font-size: 15px; font-weight: 650;
        padding-left: 0px; padding-top: 0px;
    }
    QFrame#dashboardTopBar QComboBox#topProfileCombo::drop-down {
        width: 20px; border: none;
    }
    QFrame#dashboardTopBar QComboBox#topProfileCombo:hover,
    QFrame#dashboardTopBar QComboBox#topProfileCombo:focus {
        background: rgba(25, 82, 115, 115);
    }
    """)
    # Mesmo QComboBox, mesmos sinais, mesma alteração do perfil ativo.
    lay=painel.layout()
    if lay is not None:
        lay.setContentsMargins(10,5,10,5)
        lay.setSpacing(3)
    profile=painel.findChild(QFrame,"topProfileBar")
    if profile is not None:
        profile.setFixedHeight(44)
        profile.setMinimumWidth(222)
        profile.setMaximumWidth(239)
        pl=profile.layout()
        if pl is not None:
            pl.setContentsMargins(4,2,4,2)
            pl.setSpacing(7)
        rotulo=profile.findChild(QLabel,"topProfileLabel")
        if rotulo is not None:
            rotulo.hide()   # O valor com ícone já identifica o perfil.
        icone=profile.findChild(QLabel,"premiumHeaderProfileIcon")
        if icone is not None:
            icone.setFixedSize(25,28)
        from PySide6.QtWidgets import QComboBox
        combo=profile.findChild(QComboBox,"topProfileCombo")
        if combo is not None:
            combo.setMinimumWidth(150)
            combo.setMaximumWidth(187)
            combo.setFixedHeight(30)
            combo.setAccessibleName("Perfil ativo")
    return painel
